
const DUNGEON_MONSTER_IMAGES=["","","",""];
const DUNGEON_MONSTER_NAMES=['アリへい','ガンリュウム','ガイコツ騎士','マガンメン'];
function applyDungeonMonster(index){
 const i=Math.max(0,Math.min(3,Number(index)||0));
 window.CHITEI_FORCE_ENEMY_FIRST=(i===2||i===3);
 const portrait=document.getElementById('monsterPortrait');
 if(portrait)portrait.src='data:image/webp;base64,'+DUNGEON_MONSTER_IMAGES[i];
 const name=document.querySelector('#enemyBoxStat .name');if(name)name.textContent=DUNGEON_MONSTER_NAMES[i];
}
applyDungeonMonster(__MONSTER_INDEX__);

window.addEventListener('message',ev=>{
 if(ev.source!==window.parent||ev.data?.type!=='chitei-item-init')return;
 const items=ev.data.items||{};
 potion=Math.max(0,Math.floor(Number(items.heal)||0));
 dice456=Math.max(0,Math.floor(Number(items.dice)||0));
 brokenShield=Math.max(0,Math.floor(Number(items.shield)||0));
 updateItemIndicators();ui();
});
